"use strict";
import ToggleLend from "components/ToggleLend";
import { Flex } from "ui/src";
import { EarnContextProvider, useEarnContext } from "./ContextProvider";
import ConfirmModal from "./components/ConfirmModal";
import DepositWithdrawPopupModal from "./components/DepositWithdrawPopupModal";
import EarnCard from "./components/EarnCard";
import { EarnTable } from "./components/EarnTable";
import EarnTop from "./components/EarnTop";
import ReviewModal from "./components/ReviewModal";
import ToggleTab from "./components/ToggleTab";
function EarnContent() {
  const { activeTab, transactionStep, selectedVault, closeTransaction, transactionType, openTransaction } = useEarnContext();
  return <Flex
    mt="$spacing24"
    width="100%"
    px="$spacing40"
    maxWidth={1200}
    pb={"$spacing40"}
    $xl={{
      px: "$spacing12",
      mx: "auto"
    }}
  >
      <ToggleLend />
      {
    /* <EarnTopChart /> */
  }
      <ToggleTab />
      {activeTab === "vaults" && <EarnTop />}
      <Flex $lg={{ display: "none" }}>
        <EarnTable showActions={activeTab === "positions"} />
      </Flex>
      <Flex display="none" $lg={{ display: "block" }}>
        <EarnCard />
      </Flex>

      {transactionStep === "input" && selectedVault && <DepositWithdrawPopupModal
    isOpen={true}
    vault={selectedVault}
    onClose={closeTransaction}
    type={transactionType}
  />}
      {transactionStep === "review" && selectedVault && <ReviewModal isOpen={true} onClose={closeTransaction} vault={selectedVault} />}
      {transactionStep === "confirm" && selectedVault && <ConfirmModal isOpen={true} onClose={closeTransaction} vault={selectedVault} />}
    </Flex>;
}
export default function Earn() {
  return <EarnContextProvider>
      <EarnContent />
    </EarnContextProvider>;
}
